'use strict';

// MODULES //

var tape = require( 'tape' );
var isPositiveInteger = require( '@stdlib/assert/is-positive-integer' ).isPrimitive;
var dtypes = require( '@stdlib/ndarray/dtypes' );
var promoteDataTypes = require( '@stdlib/ndarray/base/promote-dtypes' );
var quinaryBlockSize = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof quinaryBlockSize, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a block size', function test( t ) {
	var combo;
	var dt;
	var pt;
	var v;
	var i;
	var j;

	// NOTE: we don't test for exact block size values, as we shouldn't need to make guarantees regarding the block size for any particular set of dtypes. This function is meant to be opaque, and we want to reserve the right to silently update/change return values in the future.

	// Generate a list of dtypes:
	dt = dtypes();

	// NOTE: testing the full cartesian product of dtypes (i.e., `dt.length^5` combinations) is prohibitively expensive and exhausts available memory. Instead, cyclically rotate the dtype list to generate quintuplets, ensuring that every dtype is exercised in every argument position at least once:
	for ( i = 0; i < dt.length; i++ ) {
		combo = [];
		for ( j = 0; j < 5; j++ ) {
			combo.push( dt[ ( i+j ) % dt.length ] );
		}
		pt = promoteDataTypes( combo );
		combo.push( ( pt === null ) ? 'generic' : pt );
		v = quinaryBlockSize( combo[ 0 ], combo[ 1 ], combo[ 2 ], combo[ 3 ], combo[ 4 ], combo[ 5 ] ); // eslint-disable-line max-len
		t.strictEqual( isPositiveInteger( v ), true, 'returns a positive integer when provided ('+combo.join( ', ' )+')' );
	}

	// Sanity check that the block size for dtypes with wider bit widths is smaller than for dtypes with shorter bit widths...
	t.strictEqual( quinaryBlockSize( 'complex128', 'complex128', 'complex128', 'complex128', 'complex128', 'complex128' ) < quinaryBlockSize( 'int8', 'int8', 'int8', 'int8', 'int8', 'int8' ), true, 'returns expected value' );
	t.strictEqual( quinaryBlockSize( 'float64', 'float64', 'float64', 'float64', 'float64', 'float64' ) < quinaryBlockSize( 'uint8', 'uint8', 'uint8', 'uint8', 'uint8', 'uint8' ), true, 'returns expected value' );
	t.end();
});
